func testProcessoEquipamentoToManyAddOpPrceEquipamentoProcessoEqus(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a ProcessoEquipamento
	var b, c, d, e EquipamentoProcessoEqu

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, processoEquipamentoDBTypes, false, strmangle.SetComplement(processoEquipamentoPrimaryKeyColumns, processoEquipamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*EquipamentoProcessoEqu{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, equipamentoProcessoEquDBTypes, false, strmangle.SetComplement(equipamentoProcessoEquPrimaryKeyColumns, equipamentoProcessoEquColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*EquipamentoProcessoEqu{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddPrceEquipamentoProcessoEqus(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.PrceID != first.PrceID {
			t.Error("foreign key was wrong value", a.PrceID, first.PrceID)
		}
		if a.PrceID != second.PrceID {
			t.Error("foreign key was wrong value", a.PrceID, second.PrceID)
		}

		if first.R.Prce != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Prce != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.PrceEquipamentoProcessoEqus[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.PrceEquipamentoProcessoEqus[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.PrceEquipamentoProcessoEqus().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

